using System;
using System.Collections;
using System.Linq;
using ExitGames.Client.Photon;
using LogicLegends.OpenArchive.Hunting;
using Photon.Pun;
using Photon.Realtime;
using UnityEngine;

namespace LogicLegends.OpenArchive.Topics.Editor
{
    /// <summary>T6 scenarios exercise the existing shared-session protocol through independent Photon peers.</summary>
    public static partial class ArchiveTopicNetworkChecks
    {
        static IEnumerator FormulaPlace(Peer peer,int item,int slot){var st=session.stations[5];var q=session.Question(5);yield return Move(peer,st,st.CurrentItemPosition(item,q,session.State.stations[5]));yield return Send(peer,5,ArchiveAction.Pick,item);yield return Move(peer,st,st.SlotPosition(slot,q));yield return Send(peer,5,ArchiveAction.Place,slot);}
        static IEnumerator FormulaArrange(Peer peer,int[] answer){for(int i=0;i<answer.Length;i++)if(session.State.stations[5].placements[i]!=answer[i])yield return FormulaPlace(peer,answer[i],i);}
        static IEnumerator InductionFlow(Peer a,string room){
            var st=session.stations[5];Status="T6 shared formulas and attribution";yield return Move(a,st,ArchiveTopicStation.BookPosition+Vector3.back*1.7f);yield return Send(a,5,ArchiveAction.Start);var state=session.State.stations[5];double deadline=state.timerDeadline;var q=session.Question(5);Check(session.ActiveTopic==5&&state.timerRunning&&state.timerLimit==session.inductionTimeLimitSeconds*session.PacingMultiplier&&state.timerActor==a.Actor,"Guest Book starts the authenticated shared six-minute induction clock");
            yield return FormulaPlace(a,(q.expected[0]+1)%q.items.Length,0);var b=Connect("Archive guest B QA");yield return Wait(()=>b.client.State==ClientState.ConnectedToMasterServer,"T6 guest B connected");b.client.OpJoinRoom(new EnterRoomParams{RoomName=room});yield return Wait(()=>b.client.InRoom&&b.state!=null&&b.state.stations[5].placements.Length==1,"T6 late guest checkpoint");Spawn(b,Position(st,Vector3.zero));yield return Wait(()=>session.ActorPlayer(b.Actor)!=null,"T6 guest B avatar");Check(b.state.stations[5].placements.SequenceEqual(state.placements)&&Math.Abs(b.state.stations[5].timerDeadline-deadline)<.000001,"Late join restores the chosen base formula and exact deadline");
            yield return Send(a,5,ArchiveAction.Submit,spoof:true);Check(state.round==0&&session.State.mistakes.Count==1&&session.State.mistakes[0].actor==a.Actor&&state.lastAnswerActor==a.Actor,"Wrong formula charges its authenticated sender despite a forged actor field");int revision=session.State.revision;Packet(a,lastCommand);yield return .25f;Check(session.State.revision==revision&&session.State.mistakes.Count==1,"Replayed formula submission cannot charge a second mistake");
            var fake=JsonUtility.FromJson<ArchiveTeamState>(JsonUtility.ToJson(session.State));fake.revision+=1000;fake.stations[5].phase=2;b.client.OpRaiseEvent(ArchiveTopicSession.SnapshotEvent,new object[]{ArchiveTopicSession.Channel,JsonUtility.ToJson(fake)},new RaiseEventOptions{Receivers=ReceiverGroup.All},SendOptions.SendReliable);yield return .25f;Check(session.ActiveTopic==5&&a.state.stations[5].phase==1,"Guest snapshot cannot forge induction completion");yield return FormulaArrange(b,q.expected);yield return Send(b,5,ArchiveAction.Submit);Check(state.round==1&&state.phase==0&&state.reveal.Contains(q.details[q.expected[0]])&&Math.Abs(state.timerDeadline-deadline)<.000001,"Teammate corrects the same base formula and shares its accepted equality");
            state.timerDeadline=ArchiveTopicSession.TimerClock-.01;yield return Wait(()=>state.timerExpired&&b.state.stations[5].timerExpired,"T6 Book gate timeout replicates",8);Check(state.round==1&&state.placements.Length==0&&b.state.stations[5].placements.Length==0&&session.State.mistakes.Last().actor==a.Actor,"Gate timeout preserves solved progress without inheriting a previous single-slot answer");yield return BlockedBook(b,4,"Expired induction still reserves the unfinished team topic");yield return Move(b,st,ArchiveTopicStation.BookPosition+Vector3.back*1.7f);yield return Send(b,5,ArchiveAction.Start);q=session.Question(5);deadline=state.timerDeadline;Check(state.placements.SequenceEqual(new[]{-1})&&state.timerAttempt==2&&state.timerActor==b.Actor,"Teammate Book starts the hypothesis with an empty anchor and a fresh attempt");
            yield return Move(a,st,st.CurrentItemPosition(0,q,state));yield return Send(a,5,ArchiveAction.Pick,0);yield return Move(b,st,st.CurrentItemPosition(0,q,state));revision=session.State.revision;Packet(b,Command(b,5,ArchiveAction.Pick,0));yield return .25f;Check(session.State.revision==revision&&state.carries.Count==1&&state.carries[0].actor==a.Actor,"Guest cannot steal a teammate's carried formula scroll");
            PhotonNetwork.SetMasterClient(PhotonNetwork.CurrentRoom.GetPlayer(a.Actor));yield return Wait(()=>!PhotonNetwork.IsMasterClient&&a.client.CurrentRoom.MasterClientId==a.Actor,"T6 live master handoff");a.client.CurrentRoom.SetMasterClient(a.client.CurrentRoom.GetPlayer(PhotonNetwork.LocalPlayer.ActorNumber));yield return Wait(()=>PhotonNetwork.IsMasterClient,"T6 Editor regains authority");yield return .2f;state=session.State.stations[5];Check(state.round==1&&state.carries.Count==1&&state.carries[0].actor==a.Actor&&Math.Abs(state.timerDeadline-deadline)<.000001,"Master handoff keeps solved work, carried formula and deadline");
            int former=a.Actor;a.client.Disconnect();yield return Wait(()=>PhotonNetwork.CurrentRoom.GetPlayer(former)==null,"T6 starter leaves");yield return .2f;Check(state.carries.Count==0&&session.ActiveTopic==5&&session.ActorName(former)=="Archive guest A QA"&&session.State.mistakes[0].actor==former,"Departure returns held scrolls and retains reservation plus mistake identity");
            yield return FormulaPlace(b,q.expected[0],0);var kept=state.placements.ToArray();int before=session.State.mistakes.Count;state.timerDeadline=ArchiveTopicSession.TimerClock-.01;yield return Wait(()=>state.timerExpired&&b.state.stations[5].timerExpired,"T6 active formula timeout replicates",8);Check(state.round==1&&state.placements.SequenceEqual(kept)&&session.State.mistakes.Count==before+1&&session.State.mistakes.Last().actor==b.Actor,"Active timeout keeps the hypothesis and charges the current Book activator once");yield return Move(b,st,ArchiveTopicStation.BookPosition+Vector3.back*1.7f);yield return Send(b,5,ArchiveAction.Start);Check(state.placements.SequenceEqual(kept)&&state.timerAttempt==3,"Guest retry retains the exact unfinished hypothesis formula");yield return BlockedBook(b,0,"Active induction cannot be exchanged for another topic");
            Status="T6 capture restrictions";int available=(q.expected[0]+1)%q.items.Length;yield return Move(b,st,st.CurrentItemPosition(available,q,state));var capture=session.hunting.GetSnapshot();capture.state=(int)KhezuHuntState.Caught;capture.target=capture.caught=b.Actor;capture.captureSerial++;capture.huntSerial++;capture.capturePosition=session.ActorPlayer(b.Actor).transform.position;capture.captureAnchorValid=true;capture.captureStartedAt=KhezuHuntingController.EncounterClock-3;capture.encounterPhase=4;capture.awake=true;capture.pending=false;capture.animation="Idle";capture.animationSpeed=1;session.hunting.ApplySnapshot(capture,true);yield return .25f;Check(!session.CanAct(b.Actor)&&session.CanAct(PhotonNetwork.LocalPlayer.ActorNumber),"Only the captured player loses induction interaction authority");revision=session.State.revision;Packet(b,Command(b,5,ArchiveAction.Pick,available));yield return .25f;Check(session.State.revision==revision&&state.carries.Count==0,"Captured guest cannot pick a valid nearby unheld formula scroll");session.hunting.Request(KhezuCommand.Sleep);yield return .2f;
            Status="All five induction challenges over Photon";for(int r=state.round;r<5;r++){
                if(state.phase==0){yield return Move(b,st,ArchiveTopicStation.BookPosition+Vector3.back*1.7f);yield return Send(b,5,ArchiveAction.Start);}q=session.Question(5);yield return FormulaArrange(b,q.expected);yield return Send(b,5,ArchiveAction.Submit);Check(state.round==r+1&&b.state.stations[5].round==r+1&&q.expected.All(i=>state.reveal.Contains(q.details[i])),"Photon induction stage "+(r+1)+" shares its accepted formulas and progress");
            }
            Check(state.phase==2&&!state.timerRunning&&session.ActiveTopic==-1&&state.reveal.Contains("for every integer n ≥ 1"),"Shared full proof freezes time and unlocks the next topic");Check(session.State.stations.Where(s=>s.topic!=5).All(s=>s.round==0&&s.timerAttempt==0),"T6 network play preserves every other topic's state and clocks");Status="Completed T6 transport checks";
        }
    }
}
